    apply (lap_of_run tm Cc true true cho_1RB1RD_1RC0LC_1LA1LA_1LC0RD B0_1RB1RD_1RC0LC_1LA1LA_1LC0RD B1_1RB1RD_1RC0LC_1LA1LA_1LC0RD 4 16 p j' [] []).
