      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB____0LC0RB_0LD1LC_1RA1RD
      with (l := [SWin 2; SCycL 2 0; SWin 1; SWinL 3]).
